var n=`1197-rice-and-beans-belizean-style`;var a=`world-1197`;var t=`BZ`;var s=`central-america-caribbean`;var r=4;var o=461;var l={en:`Rice and Beans Belizean Style`,ua:`Рис із квасолею по-белізьки`};var d={en:`Rice and Beans Belizean Style is a dish from Belize prepared with kidney beans, yellow onion, garlic, white rice. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Рис із квасолею по-белізьки, страва кухні країни Беліз, яку готують із таких продуктів: червона квасоля кідні, жовта цибуля, часник, білий рис. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var c=[{en:`Soak the dried beans in ample clean cold water for about 330 minutes, drain and discard the soaking water; cook fully in fresh water.`,ua:`Замочіть сухі бобові у достатній кількості чистої холодної води на приблизно 330 хвилин, злийте її й повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:330,i:[[`kidney-beans`,380,`g`],[`water`,900,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 95 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 95 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:95,i:[[`water`,1050,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,180,`g`],[`garlic`,4,`clove`],[`coconut-oil`,38,`ml`]]},{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 25 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 25 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`white-rice`,420,`g`],[`coconut-milk`,350,`ml`],[`water`,350,`ml`],[`thyme`,4,`sprig`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`ground-black-pepper`,3,`g`]]}];var u={slug:n,id:a,country:`BZ`,region:s,servings:4,minutes:461,title:l,text:d,steps:c};export{t as country,u as default,a as id,o as minutes,s as region,r as servings,n as slug,c as steps,d as text,l as title};